student:
{
    "label": "Learniq",
    "collections": [
        {
            "id": "studentGrades",
            "register": "learniq",
            "schema": "grade-entry",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "label": "My grades",
            "listable": true,
            "minTrust": "low",
            "fields": [
                "learnerRef",
                "courseId",
                "courseName",
                "methodName",
                "methodBlock",
                "weight",
                "curriculumPlanId",
                "componentId",
                "value",
                "gradeScaleId",
                "period",
                "gradedAt"
            ],
            "columns": [
                {
                    "field": "courseName",
                    "label": "Subject"
                },
                {
                    "field": "gradedAt",
                    "label": "Date",
                    "render": "date"
                },
                {
                    "field": "value",
                    "label": "Grade"
                }
            ]
        },
        {
            "id": "studentFinalGrades",
            "register": "learniq",
            "schema": "final-grade",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "label": "My final grades",
            "listable": true,
            "minTrust": "low",
            "fields": [
                "learnerRef",
                "courseId",
                "programmeId",
                "curriculumPlanId",
                "gradeScaleId",
                "value",
                "passed",
                "lastRecomputedAt"
            ]
        },
        {
            "id": "studentAttendance",
            "register": "learniq",
            "schema": "attendance-record",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "label": "My attendance",
            "listable": true,
            "minTrust": "low",
            "fields": [
                "learnerRef",
                "sessionId",
                "cohortId",
                "status",
                "minutesAttended",
                "markedAt"
            ]
        },
        {
            "id": "studentEnrolments",
            "register": "learniq",
            "schema": "enrolment",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "label": "My enrolments",
            "listable": true,
            "fields": [
                "learnerRef",
                "courseId",
                "mandatory",
                "dueDate",
                "source",
                "regulationSlug",
                "cohortId"
            ],
            "contacts": {
                "provider": "ownMessageContacts",
                "composeLabel": "A message to your teacher",
                "composeHint": "Your teacher usually answers within two school days."
            }
        },
        {
            "id": "studentSubmissions",
            "register": "learniq",
            "schema": "submission",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "label": "My submissions",
            "listable": true,
            "rowActions": [
                "handIn"
            ],
            "fields": [
                "learnerRef",
                "assignmentId",
                "attachmentRefs",
                "submittedAt",
                "feedbackText",
                "lifecycle"
            ]
        },
        {
            "id": "studentBpvPlacements",
            "register": "learniq",
            "schema": "bpv-placement",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "label": "My placement",
            "listable": true,
            "minTrust": "low",
            "kind": "cases",
            "steps": {
                "label": "Where do you stand?",
                "provider": "bpvPlacementSteps"
            },
            "fields": [
                "learnerRef",
                "trainingCompanyName",
                "periodFrom",
                "periodTo",
                "agreedHours",
                "hoursApprovedTotal",
                "hoursWaitingTotal",
                "hoursReturnedTotal",
                "lifecycle",
                "workdaysLabel",
                "workplaceAddress",
                "qualificationName",
                "crebo"
            ],
            "columns": [
                {
                    "field": "trainingCompanyName",
                    "label": "Training company"
                },
                {
                    "field": "hoursApprovedTotal",
                    "label": "Hours approved"
                },
                {
                    "field": "agreedHours",
                    "label": "Agreed hours"
                }
            ],
            "fieldConfigs": {
                "trainingCompanyName": {
                    "label": "Training company"
                },
                "periodFrom": {
                    "label": "From"
                },
                "periodTo": {
                    "label": "Until"
                },
                "agreedHours": {
                    "label": "Agreed hours"
                },
                "hoursApprovedTotal": {
                    "label": "Hours approved"
                },
                "hoursWaitingTotal": {
                    "label": "Waiting for approval"
                },
                "hoursReturnedTotal": {
                    "label": "Sent back"
                },
                "lifecycle": {
                    "label": "Status",
                    "valueLabels": {
                        "proposed": "Proposed",
                        "sbb-verification-pending": "Waiting for the SBB check",
                        "confirmed": "Confirmed",
                        "active": "Placement running",
                        "completed": "Finished",
                        "terminated": "Stopped early"
                    }
                },
                "workdaysLabel": {
                    "label": "Workdays"
                },
                "workplaceAddress": {
                    "label": "Address"
                },
                "qualificationName": {
                    "label": "Qualification"
                },
                "crebo": {
                    "label": "Crebo"
                }
            }
        },
        {
            "id": "studentHourWeeks",
            "register": "learniq",
            "schema": "bpv-hour-week",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "label": "My hours",
            "listable": true,
            "minTrust": "low",
            "fields": [
                "learnerRef",
                "bpvPlacementId",
                "isoWeek",
                "hoursSubmitted",
                "submittedAt",
                "hoursApproved",
                "approvedByName",
                "approvedAt",
                "note",
                "lifecycle"
            ],
            "columns": [
                {
                    "field": "isoWeek",
                    "label": "Week"
                },
                {
                    "field": "hoursSubmitted",
                    "label": "Hours you entered"
                },
                {
                    "field": "submittedAt",
                    "label": "Sent on",
                    "render": "date"
                },
                {
                    "field": "hoursApproved",
                    "label": "Hours approved"
                },
                {
                    "field": "lifecycle",
                    "label": "Status",
                    "valueLabels": {
                        "submitted": "Waiting for approval",
                        "approved": "Approved",
                        "corrected": "Approved with a correction",
                        "rejected": "Sent back"
                    }
                }
            ]
        },
        {
            "id": "studentWorkProcesses",
            "register": "learniq",
            "schema": "werkproces-progress",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "label": "Work processes",
            "listable": false,
            "minTrust": "low",
            "fields": [
                "learnerRef",
                "bpvPlacementId",
                "werkprocesCode",
                "werkprocesLabel",
                "hoursSpent",
                "selfAssessment"
            ],
            "columns": [
                {
                    "field": "werkprocesCode",
                    "label": "Code"
                },
                {
                    "field": "werkprocesLabel",
                    "label": "Work process"
                },
                {
                    "field": "hoursSpent",
                    "label": "Hours"
                },
                {
                    "field": "selfAssessment",
                    "label": "Your estimate",
                    "valueLabels": {
                        "goed": "Good",
                        "voldoende": "Sufficient",
                        "onvoldoende": "Insufficient"
                    }
                }
            ],
            "rowActions": [
                "fillInSelfAssessment"
            ]
        },
        {
            "id": "studentTrainers",
            "register": "learniq",
            "schema": "praktijkopleider",
            "scopeField": "trainingCompanyName",
            "scopeClaim": "learnerRef",
            "via": {
                "register": "learniq",
                "schema": "bpv-placement",
                "scopeField": "learnerRef",
                "targetField": "practicalTrainerId"
            },
            "label": "Your trainer",
            "listable": false,
            "minTrust": "low",
            "fields": [
                "givenName",
                "familyName",
                "trainingCompanyName"
            ]
        },
        {
            "id": "studentSchoolCoaches",
            "register": "learniq",
            "schema": "staff",
            "scopeField": "ncUserId",
            "scopeClaim": "learnerRef",
            "via": {
                "register": "learniq",
                "schema": "bpv-placement",
                "scopeField": "learnerRef",
                "targetField": "schoolCoachId",
                "match": "scopeField"
            },
            "label": "Your BPV supervisor at school",
            "listable": false,
            "minTrust": "low",
            "fields": [
                "ncUserId"
            ],
            "columns": [
                {
                    "field": "ncUserId",
                    "label": "BPV supervisor",
                    "render": "user"
                }
            ]
        },
        {
            "id": "studentExcuseRequests",
            "register": "learniq",
            "schema": "excuse-request",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "label": "My absence excuses",
            "listable": true,
            "fields": [
                "learnerRef",
                "dateFrom",
                "dateTo",
                "reason",
                "reasonKind",
                "attachmentRef",
                "lifecycle",
                "decidedAt"
            ]
        },
        {
            "id": "studentInbox",
            "kind": "inbox",
            "register": "learniq",
            "schema": "grade-notification",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "label": "Notifications",
            "listable": true,
            "fields": [
                "learnerRef",
                "event",
                "courseId",
                "courseName",
                "visibleFrom"
            ],
            "visibleFromField": "visibleFrom",
            "messageFields": {
                "subject": "courseName",
                "receivedAt": "visibleFrom"
            }
        },
        {
            "id": "studentTests",
            "kind": "timedTask",
            "register": "learniq",
            "schema": "assessment-result",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "label": "My tests",
            "listable": true,
            "minTrust": "low",
            "fields": [
                "assessmentId",
                "assessmentTitle",
                "lifecycle",
                "attemptNumber",
                "startedAt",
                "submittedAt"
            ],
            "timedTask": {
                "available": "listTests",
                "start": "startTest",
                "answer": "saveTestAnswer",
                "submit": "submitTest",
                "result": "readTestResult"
            }
        },
        {
            "id": "studentHomework",
            "register": "learniq",
            "schema": "assignment",
            "scopeField": "learnerRefs",
            "scopeClaim": "learnerRef",
            "filter": {
                "lifecycle": "published"
            },
            "label": "To hand in",
            "listable": true,
            "minTrust": "low",
            "fields": [
                "title",
                "instructions",
                "dueAt",
                "cohortId",
                "allowLateSubmission",
                "lifecycle"
            ],
            "columns": [
                {
                    "field": "title",
                    "label": "To do"
                },
                {
                    "field": "dueAt",
                    "label": "Hand in by",
                    "render": "date"
                }
            ]
        },
        {
            "id": "studentAttendanceSummary",
            "register": "learniq",
            "schema": "attendance-summary",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "label": "Absence this school year",
            "listable": false,
            "minTrust": "low",
            "fields": [
                "learnerRef",
                "schoolYear",
                "absentDays",
                "absentAuthorisedDays",
                "absentUnauthorisedDays",
                "lateCount",
                "lateMinutes"
            ]
        },
        {
            "id": "studentSessions",
            "register": "learniq",
            "schema": "session",
            "scopeField": "cohortId",
            "scopeClaim": "learnerRef",
            "via": {
                "register": "learniq",
                "schema": "enrolment",
                "scopeField": "learnerRef",
                "targetField": "cohortId",
                "match": "scopeField",
                "when": {
                    "field": "lifecycle",
                    "in": [
                        "active"
                    ]
                }
            },
            "label": "My timetable",
            "listable": true,
            "minTrust": "low",
            "fields": [
                "cohortId",
                "courseId",
                "title",
                "startsAt",
                "endsAt",
                "location",
                "changeReasonKind",
                "changeReason",
                "lifecycle"
            ],
            "fieldConfigs": {
                "changeReasonKind": {
                    "label": "Change",
                    "valueLabels": {
                        "room-unavailable": "Other room",
                        "teacher-absence": "Other teacher",
                        "timetable-change": "Changed"
                    }
                }
            },
            "columns": [
                {
                    "field": "startsAt",
                    "label": "Starts at",
                    "render": "datetime"
                },
                {
                    "field": "title",
                    "label": "Subject"
                },
                {
                    "field": "location",
                    "label": "Room"
                }
            ]
        }
    ],
    "actions": [
        {
            "id": "createSubmission",
            "type": "create",
            "label": "Hand in an assignment",
            "register": "learniq",
            "schema": "submission",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "minTrust": "low",
            "fields": [
                "assignmentId",
                "attachmentRefs"
            ],
            "fieldConfigs": {
                "assignmentId": {
                    "label": "The work you are handing in",
                    "required": true
                },
                "attachmentRefs": {
                    "type": "file",
                    "label": "Your work",
                    "multiple": true,
                    "accept": [
                        ".pdf",
                        ".doc",
                        ".docx",
                        ".odt",
                        ".pptx",
                        ".jpg",
                        ".png"
                    ],
                    "maxSizeMb": 20
                }
            },
            "submitLabel": "Hand in your work"
        },
        {
            "id": "submitHourWeek",
            "type": "create",
            "label": "Enter the hours of a week",
            "register": "learniq",
            "schema": "bpv-hour-week",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "minTrust": "low",
            "fields": [
                "bpvPlacementId",
                "isoWeek",
                "hoursSubmitted"
            ],
            "crossRefs": {
                "bpvPlacementId": {
                    "register": "learniq",
                    "schema": "bpv-placement",
                    "scopeField": "learnerRef",
                    "scopeClaim": "learnerRef",
                    "required": true
                }
            },
            "optionsProviders": {
                "bpvPlacementId": {
                    "type": "collection",
                    "register": "learniq",
                    "schema": "bpv-placement",
                    "labelField": "trainingCompanyName",
                    "valueField": "id"
                }
            },
            "fieldConfigs": {
                "bpvPlacementId": {
                    "label": "Your placement",
                    "required": true
                },
                "isoWeek": {
                    "label": "The week, as 2026-W39",
                    "required": true
                },
                "hoursSubmitted": {
                    "label": "Hours you worked",
                    "required": true
                }
            },
            "submitLabel": "Send these hours",
            "successMessage": "Your hours are with your workplace trainer. You see her decision in the list."
        },
        {
            "id": "fillInSelfAssessment",
            "type": "update",
            "label": "Fill in now",
            "register": "learniq",
            "schema": "werkproces-progress",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "minTrust": "low",
            "fields": [
                "selfAssessment"
            ],
            "requiredFields": [
                "selfAssessment"
            ],
            "optionsProviders": {
                "selfAssessment": {
                    "type": "static",
                    "options": [
                        {
                            "value": "goed",
                            "label": "Good"
                        },
                        {
                            "value": "voldoende",
                            "label": "Sufficient"
                        },
                        {
                            "value": "onvoldoende",
                            "label": "Insufficient"
                        }
                    ]
                }
            },
            "fieldConfigs": {
                "selfAssessment": {
                    "label": "Your estimate",
                    "required": true,
                    "widget": "choices",
                    "valueLabels": {
                        "goed": "Good",
                        "voldoende": "Sufficient",
                        "onvoldoende": "Insufficient"
                    }
                }
            },
            "submitLabel": "Save my estimate",
            "successMessage": "Your estimate is saved. Your workplace trainer and your coach see it at the interim assessment."
        },
        {
            "id": "createExcuseRequest",
            "type": "create",
            "label": "Report an absence",
            "register": "learniq",
            "schema": "excuse-request",
            "scopeField": "learnerRef",
            "scopeClaim": "learnerRef",
            "minTrust": "low",
            "fields": [
                "dateFrom",
                "dateTo",
                "reason",
                "reasonKind",
                "attachmentRef"
            ],
            "fieldConfigs": {
                "dateFrom": {
                    "label": "First day you are absent",
                    "required": true,
                    "widget": "dateChoices",
                    "dateChoices": 2
                },
                "dateTo": {
                    "label": "Last day you are absent",
                    "required": true,
                    "widget": "dateChoices",
                    "dateChoices": 2,
                    "requiredMessage": "Choose the last day you are absent."
                },
                "reason": {
                    "label": "Reason",
                    "required": true
                },
                "reasonKind": {
                    "label": "Kind of absence",
                    "required": true,
                    "valueLabels": {
                        "illness": "Illness",
                        "medical-appointment": "Medical appointment",
                        "family-circumstance": "Family circumstance",
                        "religious-observance": "Religious observance",
                        "bereavement": "Bereavement",
                        "other": "Other"
                    },
                    "widget": "choices",
                    "choiceOptions": [
                        "illness",
                        "medical-appointment"
                    ],
                    "otherLabel": "Another reason"
                },
                "attachmentRef": {
                    "type": "file",
                    "label": "Attachment",
                    "multiple": false,
                    "accept": [
                        ".pdf",
                        ".jpg",
                        ".jpeg",
                        ".png",
                        ".heic",
                        ".doc",
                        ".docx",
                        ".odt"
                    ],
                    "maxSizeMb": 10
                }
            },
            "submitLabel": "Report your absence",
            "successMessage": "The school has your report. You see the decision in the list of absence reports."
        },
        {
            "id": "listTests",
            "type": "endpoint-forward",
            "label": "Tests you can take",
            "endpoint": "/apps/learniq/api/portal/assessments",
            "method": "POST",
            "minTrust": "low",
            "fields": [],
            "subjectField": "learnerRef",
            "scopeClaim": "learnerRef"
        },
        {
            "id": "startTest",
            "type": "endpoint-forward",
            "label": "Start a test",
            "endpoint": "/apps/learniq/api/portal/assessments/start",
            "method": "POST",
            "minTrust": "low",
            "fields": [
                "taskId",
                "accessCode"
            ],
            "subjectField": "learnerRef",
            "scopeClaim": "learnerRef"
        },
        {
            "id": "saveTestAnswer",
            "type": "endpoint-forward",
            "label": "Save an answer",
            "endpoint": "/apps/learniq/api/portal/assessments/answer",
            "method": "POST",
            "minTrust": "low",
            "fields": [
                "attemptId",
                "itemId",
                "response"
            ],
            "subjectField": "learnerRef",
            "scopeClaim": "learnerRef"
        },
        {
            "id": "submitTest",
            "type": "endpoint-forward",
            "label": "Hand in a test",
            "endpoint": "/apps/learniq/api/portal/assessments/submit",
            "method": "POST",
            "minTrust": "low",
            "fields": [
                "attemptId"
            ],
            "subjectField": "learnerRef",
            "scopeClaim": "learnerRef"
        },
        {
            "id": "readTestResult",
            "type": "endpoint-forward",
            "label": "View a result",
            "endpoint": "/apps/learniq/api/portal/assessments/result",
            "method": "POST",
            "minTrust": "low",
            "fields": [
                "attemptId"
            ],
            "subjectField": "learnerRef",
            "scopeClaim": "learnerRef"
        },
        {
            "id": "handIn",
            "type": "endpoint-forward",
            "label": "Hand in",
            "endpoint": "/apps/learniq/api/portal/submissions/hand-in",
            "method": "POST",
            "minTrust": "low",
            "fields": [
                "submissionId"
            ],
            "subjectField": "learnerRef",
            "scopeClaim": "learnerRef",
            "rowField": "submissionId",
            "rowWhen": {
                "field": "lifecycle",
                "in": [
                    "draft"
                ]
            }
        },
        {
            "id": "listCatalogue",
            "type": "endpoint-forward",
            "label": "Course catalogue",
            "endpoint": "/apps/learniq/api/portal/catalogue",
            "method": "POST",
            "minTrust": "low",
            "fields": [
                "search"
            ],
            "subjectField": "learnerRef",
            "scopeClaim": "learnerRef"
        },
        {
            "id": "signUpForCourse",
            "type": "endpoint-forward",
            "label": "Sign up",
            "endpoint": "/apps/learniq/api/portal/catalogue/sign-up",
            "method": "POST",
            "minTrust": "low",
            "fields": [
                "courseId",
                "programmeId"
            ],
            "subjectField": "learnerRef",
            "scopeClaim": "learnerRef"
        },
        {
            "id": "withdrawSignUp",
            "type": "endpoint-forward",
            "label": "Withdraw",
            "endpoint": "/apps/learniq/api/portal/catalogue/withdraw",
            "method": "POST",
            "minTrust": "low",
            "fields": [
                "enrolmentId"
            ],
            "subjectField": "learnerRef",
            "scopeClaim": "learnerRef"
        },
        {
            "id": "listWorkGroups",
            "type": "endpoint-forward",
            "label": "My work groups",
            "endpoint": "/apps/learniq/api/portal/work-groups",
            "method": "POST",
            "minTrust": "low",
            "fields": [],
            "subjectField": "learnerRef",
            "scopeClaim": "learnerRef"
        },
        {
            "id": "joinWorkGroup",
            "type": "endpoint-forward",
            "label": "Join",
            "endpoint": "/apps/learniq/api/portal/work-groups/join",
            "method": "POST",
            "minTrust": "low",
            "fields": [
                "groupId"
            ],
            "subjectField": "learnerRef",
            "scopeClaim": "learnerRef"
        },
        {
            "id": "leaveWorkGroup",
            "type": "endpoint-forward",
            "label": "Leave",
            "endpoint": "/apps/learniq/api/portal/work-groups/leave",
            "method": "POST",
            "minTrust": "low",
            "fields": [
                "groupId"
            ],
            "subjectField": "learnerRef",
            "scopeClaim": "learnerRef"
        },
        {
            "id": "checkIn",
            "type": "endpoint-forward",
            "label": "Check in to a lesson",
            "endpoint": "/apps/learniq/api/portal/check-in",
            "method": "POST",
            "minTrust": "low",
            "fields": [
                "code"
            ],
            "subjectField": "learnerRef",
            "scopeClaim": "learnerRef"
        }
    ],
    "pages": [
        {
            "id": "studentOverview",
            "label": "Overview",
            "icon": "ViewDashboard",
            "group": "My space",
            "home": true,
            "blocks": [
                {
                    "type": "greeting"
                },
                {
                    "type": "calendar",
                    "label": "Your timetable today",
                    "display": "timetable",
                    "range": "day",
                    "firstLabel": "Your first lesson",
                    "sources": [
                        {
                            "collection": "studentSessions",
                            "startField": "startsAt",
                            "endField": "endsAt",
                            "titleField": "title",
                            "metaField": "location",
                            "noteField": "changeReason",
                            "statusField": "changeReasonKind",
                            "cancelledWhen": {
                                "field": "lifecycle",
                                "in": [
                                    "cancelled"
                                ]
                            }
                        }
                    ]
                },
                {
                    "type": "cta",
                    "page": "studentSessions",
                    "label": "Whole week"
                },
                {
                    "type": "tasks",
